import backtrader as bt


class IntradayGapFadeStrategy(bt.Strategy):
    params = (
        ("gap_threshold", 1.0),
    )

    def __init__(self):
        self.order = None
        self.stop_order = None
        self.current_day = None
        self.prior_regular_close = None
        self.entered_today = False
        self.entry_stop_price = None
        self.pending_reverse = None

    def _submit_entry(self, direction, stop_price):
        self.entry_stop_price = stop_price
        if direction == "long":
            self.order = self.buy()
        else:
            self.order = self.sell()
        self.order.addinfo(role="entry", direction=direction)

    def _submit_session_exit(self, role="session_exit"):
        if self.stop_order is not None:
            self.cancel(self.stop_order)
        self.order = self.close()
        if self.order is not None:
            self.order.addinfo(role=role)

    def notify_order(self, order):
        if order.status in (order.Submitted, order.Accepted):
            return

        role = order.info.get("role", "")

        if order.status == order.Completed:
            if role == "entry":
                direction = order.info.get("direction")
                if direction == "long":
                    self.stop_order = self.sell(
                        size=abs(order.executed.size),
                        exectype=bt.Order.Stop,
                        price=self.entry_stop_price,
                    )
                else:
                    self.stop_order = self.buy(
                        size=abs(order.executed.size),
                        exectype=bt.Order.Stop,
                        price=self.entry_stop_price,
                    )
                self.stop_order.addinfo(role="stop")
            elif role == "stop":
                self.stop_order = None
            elif role in ("session_exit", "reverse_exit"):
                if self.pending_reverse is not None:
                    direction, stop_price = self.pending_reverse
                    self.pending_reverse = None
                    self.order = None
                    self._submit_entry(direction, stop_price)
                    return

        if role == "stop":
            if order.status in (
                order.Completed,
                order.Canceled,
                order.Margin,
                order.Rejected,
            ):
                self.stop_order = None
        elif order.status in (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            if self.order is order:
                self.order = None

    def next(self):
        bar_datetime = self.data.datetime.datetime(0)
        bar_day = bar_datetime.date()
        bar_time = bar_datetime.time()

        if bar_day != self.current_day:
            self.current_day = bar_day
            self.entered_today = False

            if self.prior_regular_close is not None:
                session_open = float(self.data.open[0])
                gap_pct = (
                    (session_open - self.prior_regular_close)
                    / self.prior_regular_close
                    * 100.0
                )

                direction = None
                stop_price = None
                if gap_pct >= self.p.gap_threshold:
                    direction = "short"
                    stop_price = session_open * 1.02
                elif gap_pct <= -self.p.gap_threshold:
                    direction = "long"
                    stop_price = session_open * 0.98

                if direction is not None:
                    self.entered_today = True
                    opposite_position = (
                        (direction == "long" and self.position.size < 0)
                        or (direction == "short" and self.position.size > 0)
                    )
                    if opposite_position and self.order is None:
                        self.pending_reverse = (direction, stop_price)
                        self._submit_session_exit(role="reverse_exit")
                    elif not self.position and self.order is None:
                        self._submit_entry(direction, stop_price)

        if bar_time.hour == 15 and bar_time.minute == 45:
            if self.position and self.order is None:
                self.pending_reverse = None
                self._submit_session_exit()

        self.prior_regular_close = float(self.data.close[0])
